diff --git a/io/io.cpp b/io/io.cpp
index 85f414f..f40199d 100644
--- a/io/io.cpp
+++ b/io/io.cpp
@@ -669,6 +669,56 @@ des_ce array_ce[MAX_CE];
 natl next_ce;

 // ( SOLUZIONE 2025-09-10
+extern "C" natl c_ceasyncread_n(natl id, char *buf, natl quanti)
+{
+	if (id >= next_ce) {
+		flog(LOG_WARN, "ceasyncread_n: periferica non esistente: %u", id);
+		abort_p();
+	}
+
+	if (!quanti) {
+		flog(LOG_WARN, "ceasyncread_n: quanti == 0");
+		abort_p();
+	}
+
+	if (!access(buf, quanti, true)) {
+		flog(LOG_WARN, "ceasyncread_n: buffer non valido: %p", buf);
+		abort_p();
+	}
+
+	des_ce *ce = &array_ce[id];
+	sem_wait(ce->mutex);
+
+	natl trid = 0xFFFFFFFF;
+	for (int i = 0; i < MAX_CE_ASYNC; i++) {
+		if (ce->tr[i].buf == nullptr) {
+			trid = i;
+			ce->tr[i].buf = buf;
+			ce->tr[i].quanti = quanti;
+			ce->tr[i].next = 0xFFFFFFFF;
+			if (ce->last == 0xFFFFFFFF) {
+				ce->last = trid;
+			} else {
+				ce->tr[ce->last].next = trid;
+				ce->last = trid;
+			}
+			break;
+		}
+	}
+
+	if (trid == 0xFFFFFFFF) {
+		sem_signal(ce->mutex);
+		return 0xFFFFFFFF;
+	}
+
+	if (ce->cur == 0xFFFFFFFF) {
+		ce->cur = trid;
+		outputb(1, ce->iCTL);
+	}
+
+	sem_signal(ce->mutex);
+	return trid;
+}
 //   SOLUZIONE 2025-09-10 )

 extern "C" void c_cewait(natl id, natl trid)
@@ -705,6 +755,34 @@ extern "C" void c_cewait(natl id, natl trid)
 extern "C" void estern_ce(natq id)
 {
 // ( SOLUZIONE 2025-09-10
+	for (;;) {
+		des_ce *ce = &array_ce[id];
+		sem_wait(ce->mutex);
+		if (ce->cur != 0xFFFFFFFF) {
+			outputb(0, ce->iCTL);
+			char c = inputb(ce->iRBR);
+			des_ce_tr *t = &ce->tr[ce->cur];
+			*t->buf = c;
+			t->buf++;
+			t->quanti--;
+			if (t->quanti == 0) {
+				if (t->next != 0xFFFFFFFF) {
+					ce->cur = t->next;
+					outputb(1, ce->iCTL);
+				} else {
+					ce->cur = 0xFFFFFFFF;
+				}
+				if (ce->waiting > 0) {
+					ce->waiting--;
+					sem_signal(ce->sync);
+				}
+			} else {
+				outputb(1, ce->iCTL);
+			}
+		}
+		sem_signal(ce->mutex);
+		wfi();
+	}
 //   SOLUZIONE 2025-09-10 )
 }

